<script setup>
import { ref, computed, onMounted, reactive } from 'vue'
import { FileCheck2, Plus, Edit3, Trash2, CheckCircle2, XCircle, Eye, HelpCircle, Clock, Award, Send, AlertCircle, Layers, Check, RefreshCw, BarChart2, UserCheck, X
} from 'lucide-vue-next'
import DashboardLayout from '../components/layouts/DashboardLayout.vue'
import api from '../services/api'
import { useModalStore } from '../stores/modal'
import { useCampagnesStore } from '../stores/campagnes' const modalStore = useModalStore()
const campagnesStore = useCampagnesStore() const loading = ref(false)
const tests = ref([])
const selectedCohorte = ref('')
const showModalEdit = ref(false)
const showModalPassages = ref(false)
const selectedPassages = ref([])
const activeTestTitle = ref('') const emptyTestForm = () => ({ id: null, titre: '', description: '', dureeMinutes: 30, baremeTotal: 20, notePassage: 0, etape: '', questions: [ { intitule: '', explication: '', typeQuestion: 'CHOIX_UNIQUE', points: 1, options: [ { texte: '', estCorrecte: true }, { texte: '', estCorrecte: false } } }) const form = reactive(emptyTestForm()) const optionsCampagnesCohortes = computed(() => { const result = [] campagnesStore.cohortes.forEach(cohorte => { const etapeTest = (cohorte.etapes || []).find(e => e.nom.toLowerCase().includes('test') || e.ordre === 3) if (etapeTest) { let formationNom = cohorte.formation_nom if (!formationNom && cohorte.formation) { const found = campagnesStore.formations.find(f => f.id === (typeof cohorte.formation === 'object' ? cohorte.formation.id : cohorte.formation)) if (found) formationNom = found.nom } if (!formationNom && cohorte.formation?.nom) formationNom = cohorte.formation.nom if (!formationNom) formationNom = 'Formation' result.push({ etapeId: etapeTest.id, cohorteId: cohorte.id, label: `${formationNom} - ${cohorte.nom}` }) } }) return result
}) const fetchTests = async () => { loading.value = true try { const res = await api.get('evaluations/tests/', { params: selectedCohorte.value ? { cohorte: selectedCohorte.value } : {} }) tests.value = res.data } catch (err) { modalStore.error('Erreur lors du chargement des tests QCM.') } finally { loading.value = false }
} onMounted(async () => { await campagnesStore.fetchFormations() await campagnesStore.fetchCampagnes() await campagnesStore.fetchCohortes() await fetchTests()
}) const openCreateModal = () => { Object.assign(form, emptyTestForm()) if (optionsCampagnesCohortes.value.length > 0) form.etape = optionsCampagnesCohortes.value[0].etapeId showModalEdit.value = true
} const openEditModal = (test) => { form.id = test.id form.titre = test.titre form.description = test.description || '' form.dureeMinutes = test.dureeMinutes form.baremeTotal = test.baremeTotal form.notePassage = test.notePassage form.etape = test.etape form.questions = (test.questions || []).map(q => ({ id: q.id, intitule: q.intitule, explication: q.explication || '', typeQuestion: q.typeQuestion, points: q.points, options: (q.options || []).map(o => ({ id: o.id, texte: o.texte, estCorrecte: o.estCorrecte })) })) if (form.questions.length === 0) addQuestion() showModalEdit.value = true
} const addQuestion = () => { form.questions.push({ intitule: '', explication: '', typeQuestion: 'CHOIX_UNIQUE', points: 1, options: [{ texte: '', estCorrecte: true }, { texte: '', estCorrecte: false }] })
} const removeQuestion = (idx) => { if (form.questions.length > 1) form.questions.splice(idx, 1) else modalStore.warning('Le test doit contenir au moins une question.')
} const addOption = (qIdx) => form.questions[qIdx].options.push({ texte: '', estCorrecte: false }) const removeOption = (qIdx, oIdx) => { if (form.questions[qIdx].options.length > 2) form.questions[qIdx].options.splice(oIdx, 1) else modalStore.warning('Une question doit comporter au moins 2 propositions.')
} const selectCorrectOption = (qIdx, oIdx) => { if (form.questions[qIdx].typeQuestion === 'CHOIX_UNIQUE') { form.questions[qIdx].options.forEach((opt, index) => { opt.estCorrecte = (index === oIdx) }) } else { form.questions[qIdx].options[oIdx].estCorrecte = !form.questions[qIdx].options[oIdx].estCorrecte }
} const saveTest = async () => { if (!form.titre || !form.etape) { modalStore.error('Veuillez remplir le titre et sélectionner l\'étape.'); return } for (let i = 0; i < form.questions.length; i++) { const q = form.questions[i] if (!q.intitule.trim()) { modalStore.error(`L'intitulé de la question ${i + 1} est vide.`); return } if (!q.options.some(o => o.estCorrecte)) { modalStore.error(`La question ${i + 1} doit avoir au moins une bonne réponse.`); return } } try { const payload = { titre: form.titre, description: form.description, dureeMinutes: parseInt(form.dureeMinutes), baremeTotal: parseFloat(form.baremeTotal), notePassage: parseFloat(form.notePassage), etape: form.etape, questions: form.questions } if (form.id) { await api.put(`evaluations/tests/${form.id}/`, payload); modalStore.success('Test QCM mis à jour.') } else { await api.post('evaluations/tests/', payload); modalStore.success('Test QCM créé.') } showModalEdit.value = false await fetchTests() } catch (err) { let msg = 'Erreur lors de l\'enregistrement.' if (err.response?.data) { if (typeof err.response.data === 'string') msg = err.response.data else if (err.response.data.detail) msg = err.response.data.detail else msg = Object.entries(err.response.data).map(([k, v]) => `${k}: ${Array.isArray(v) ? v.join(',') : v}`).join('\n') } modalStore.error(msg) }
} const togglePublier = async (test) => { try { const res = await api.post(`evaluations/tests/${test.id}/publier/`) test.estPublie = res.data.estPublie modalStore.success(res.data.detail) } catch (err) { modalStore.error(err.response?.data?.detail || 'Erreur lors de la publication.') }
} const deleteTest = async (test) => { const isConfirmed = await modalStore.confirm(`Supprimer le test"${test.titre}"?`, 'Cette action est irréversible.', { variant: 'danger' }) if (isConfirmed) { try { await api.delete(`evaluations/tests/${test.id}/`) modalStore.success('Test QCM supprimé.') await fetchTests() } catch (err) { modalStore.error(err.response?.data?.detail || 'Impossible de supprimer ce test.') } }
} const viewPassages = async (test) => { activeTestTitle.value = test.titre try { const res = await api.get(`evaluations/tests/${test.id}/passages/`) selectedPassages.value = res.data showModalPassages.value = true } catch (err) { modalStore.error('Erreur lors du chargement des passages.') }
}
</script> <template> <DashboardLayout> <template #header> <div class="flex items-center gap-3"> <div class="w-7 h-7 rounded-lg bg-[#E30046] flex items-center justify-center flex-shrink-0"> <FileCheck2 class="w-4 h-4 text-white" /> </div> <div> <h2 class="text-lg font-extrabold text-[#01313E] leading-tight">Tests QCM</h2> </div> </div> </template> <template #header-actions> <button @click="fetchTests" class="btn-ghost p-2 rounded-xl" title="Rafraîchir"> <RefreshCw class="w-4 h-4" :class="{ 'animate-spin': loading }" /> </button> <button @click="openCreateModal" class="btn-primary px-4 py-2 text-xs gap-1.5"> <Plus class="w-4 h-4" /> Nouveau QCM </button> </template> <!-- ── PAGE BANNER ──────────────────────────────── --> <div class="relative overflow-hidden rounded-3xl bg-[#01313E] p-6 mb-7 animate-fade-in"> <div class="absolute right-0 top-0 w-56 h-56 bg-[#E30046] rounded-full opacity-[.10] translate-x-1/3 -translate-y-1/3"></div> <div class="absolute inset-0 opacity-[.03]" style="background-image:radial-gradient(circle,#fff 1px,transparent 1px);background-size:20px 20px;"></div> <div class="relative z-10 flex flex-wrap items-center justify-between gap-4"> <div> <span class="text-[10px] font-black uppercase tracking-[.2em] text-[#E30046]">Étape 3</span> <h1 class="mt-1 text-xl font-extrabold text-white tracking-tight">Tests QCM Pédagogiques</h1> <p class="mt-1 text-white/50 text-sm">Créez et gérez les questionnaires d'évaluation en ligne.</p> </div> <div class="flex gap-3"> <div class="rounded-2xl border border-white/10 bg-white/[.06] px-5 py-3 text-center"> <p class="text-[10px] font-bold uppercase tracking-widest text-white/40 mb-0.5">Total QCM</p> <p class="text-2xl font-black text-white">{{ tests.length }}</p> </div> <div class="rounded-2xl border border-[#E30046]/30 bg-[#E30046]/10 px-5 py-3 text-center"> <p class="text-[10px] font-bold uppercase tracking-widest text-[#E30046]/70 mb-0.5">Publiés</p> <p class="text-2xl font-black text-[#E30046]">{{ tests.filter(t => t.estPublie).length }}</p> </div> </div> </div> </div> <!-- ── LOADING ──────────────────────────────────── --> <div v-if="loading" class="flex items-center justify-center py-20"> <div class="flex flex-col items-center gap-3"> <RefreshCw class="w-8 h-8 text-[#E30046] animate-spin" /> <p class="text-sm text-[#01313E]/50 font-medium">Chargement des tests…</p> </div> </div> <!-- ── EMPTY STATE ──────────────────────────────── --> <div v-else-if="tests.length === 0" class="empty-state border border-dashed border-[#01313E]/15 rounded-3xl animate-fade-in"> <div class="empty-state-icon"> <HelpCircle class="w-8 h-8" /> </div> <h3 class="text-lg font-bold text-[#01313E] mb-2">Aucun test QCM configuré</h3> <p class="text-[#01313E]/50 text-sm max-w-sm mb-6"> Créez un questionnaire pour l'Étape 3. Les candidats pourront le passer en ligne depuis leur espace. </p> <button @click="openCreateModal" class="btn-primary"> <Plus class="w-4 h-4" /> Créer le premier QCM </button> </div> <!-- ── TEST CARDS GRID ─────────────────────────── --> <div v-else class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5"> <div v-for="(test, i) in tests" :key="test.id" class="card-hover flex flex-col animate-fade-in relative overflow-hidden" :style="{ animationDelay: (i * 60) + 'ms' }" > <!-- Top accent bar --> <div class="h-1 w-full" :class="test.estPublie ? 'bg-[#E30046]' : 'bg-[#01313E]/20'"></div> <div class="p-5 flex flex-col flex-1"> <!-- Header row --> <div class="flex items-start justify-between gap-2 mb-3"> <span class="badge" :class="test.estPublie ? 'badge-red' : 'badge-outline-dark'"> {{ test.estPublie ? 'Publié' : 'Brouillon' }} </span> <span class="text-[11px] font-medium text-[#01313E]/45 truncate max-w-[140px]"> {{ test.etape_nom || 'Étape 3' }} </span> </div> <!-- Title --> <h3 class="text-base font-extrabold text-[#01313E] mb-1.5 line-clamp-2 leading-snug"> {{ test.titre }} </h3> <p class="text-xs text-[#01313E]/50 mb-4 line-clamp-2 flex-1"> {{ test.description || 'Aucune description fournie.' }} </p> <!-- Meta grid --> <div class="grid grid-cols-2 gap-y-2 gap-x-3 py-3.5 border-y border-[#01313E]/8 mb-4"> <div class="flex items-center gap-2 text-xs text-[#01313E]/70"> <div class="w-6 h-6 rounded-lg bg-[#01313E]/6 flex items-center justify-center flex-shrink-0"> <Clock class="w-3.5 h-3.5 text-[#01313E]" /> </div> {{ test.dureeMinutes }} min </div> <div class="flex items-center gap-2 text-xs text-[#01313E]/70"> <div class="w-6 h-6 rounded-lg bg-[#01313E]/6 flex items-center justify-center flex-shrink-0"> <HelpCircle class="w-3.5 h-3.5 text-[#01313E]" /> </div> {{ test.nombreQuestions || test.questions?.length || 0 }} questions </div> <div class="flex items-center gap-2 text-xs text-[#01313E]/70"> <div class="w-6 h-6 rounded-lg bg-[#E30046]/10 flex items-center justify-center flex-shrink-0"> <Award class="w-3.5 h-3.5 text-[#E30046]" /> </div> Barème : {{ test.baremeTotal }} pts </div> <div class="flex items-center gap-2 text-xs text-[#01313E]/70"> <div class="w-6 h-6 rounded-lg bg-[#01313E]/6 flex items-center justify-center flex-shrink-0"> <Layers class="w-3.5 h-3.5 text-[#01313E]" /> </div> <span class="truncate">{{ test.cohorte_nom || 'Cohorte' }}</span> </div> </div> <!-- Actions --> <div class="flex items-center justify-between"> <button @click="togglePublier(test)" class="text-xs font-bold rounded-xl px-3 py-1.5 border transition-all" :class="test.estPublie ? 'border-[#01313E]/20 text-[#01313E] hover:bg-[#01313E] hover:text-white' : 'border-[#E30046]/30 text-[#E30046] hover:bg-[#E30046] hover:text-white'" > {{ test.estPublie ? 'Dépublier' : 'Publier' }} </button> <div class="flex items-center gap-1"> <button @click="viewPassages(test)" class="p-2 rounded-lg text-[#01313E]/40 hover:bg-[#01313E]/6 hover:text-[#01313E] transition" title="Résultats candidats"> <BarChart2 class="w-4 h-4" /> </button> <button @click="openEditModal(test)" class="p-2 rounded-lg text-[#01313E]/40 hover:bg-[#01313E]/6 hover:text-[#01313E] transition" title="Éditer"> <Edit3 class="w-4 h-4" /> </button> <button @click="deleteTest(test)" class="p-2 rounded-lg text-[#01313E]/40 hover:bg-[#E30046]/8 hover:text-[#E30046] transition" title="Supprimer"> <Trash2 class="w-4 h-4" /> </button> </div> </div> </div> </div> </div> <!-- ════════════════════════════════════════════════ MODAL — CRÉER / ÉDITER QCM ════════════════════════════════════════════════ --> <Transition enter-active-class="transition duration-200" enter-="opacity-0" enter-="opacity-100" leave-active-class="transition duration-150" leave-="opacity-100" leave-="opacity-0"> <div v-if="showModalEdit" class="fixed inset-0 z-50 flex items-start justify-center p-4 pt-10 bg-[#01313E]/50 overflow-y-auto" @click.self="showModalEdit = false"> <div class="bg-white rounded-3xl max-w-4xl w-full border border-[#01313E]/10 flex flex-col max-h-[88vh] animate-fade-in"> <!-- Modal header --> <div class="flex items-center justify-between px-7 py-5 border-b border-[#01313E]/8 flex-shrink-0"> <div class="flex items-center gap-3"> <div class="w-8 h-8 rounded-xl bg-[#E30046] flex items-center justify-center"> <FileCheck2 class="w-4 h-4 text-white" /> </div> <h2 class="text-lg font-extrabold text-[#01313E]"> {{ form.id ? 'Éditer le Test QCM' : 'Nouveau Test QCM' }} </h2> </div> <button @click="showModalEdit = false" class="w-8 h-8 grid place-items-center rounded-lg text-[#01313E]/40 hover:bg-[#01313E]/6 hover:text-[#01313E] transition"> <X class="w-4 h-4" /> </button> </div> <!-- Modal body --> <div class="overflow-y-auto flex-1 px-7 py-6 space-y-6"> <!-- Infos de base --> <section> <p class="section-label">Informations générales</p> <div class="grid grid-cols-1 md:grid-cols-2 gap-4"> <div class="md:col-span-2"> <label class="form-label">Titre du test</label> <input v-model="form.titre" type="text" placeholder="Ex: Test QCM Logique & Technique" class="input-field" /> </div> <div> <label class="form-label">Campagne / Cohorte</label> <select v-model="form.etape" class="input-field"> <option value="" disabled>Sélectionner…</option> <option v-for="c in optionsCampagnesCohortes" :key="c.etapeId" :value="c.etapeId">{{ c.label }}</option> </select> <p class="text-[11px] text-[#01313E]/40 mt-1">Lié à l'Étape 3 de la cohorte sélectionnée.</p> </div> <div class="grid grid-cols-2 gap-4"> <div> <label class="form-label">Durée (minutes)</label> <input v-model="form.dureeMinutes" type="number" min="5" class="input-field" /> </div> <div> <label class="form-label">Barème Total (points)</label> <input v-model="form.baremeTotal" type="number" step="0.5" class="input-field" /> </div> </div> <div class="md:col-span-2"> <label class="form-label">Description / Instructions</label> <textarea v-model="form.description" rows="2" placeholder="Consignes destinées au candidat avant d'entamer le test…" class="input-field resize-none"></textarea> </div> </div> </section> <!-- Questions --> <section class="border-t border-[#01313E]/8 pt-6"> <div class="flex items-center justify-between mb-4"> <p class="section-label mb-0">Questions — {{ form.questions.length }}</p> <button @click="addQuestion" class="btn-secondary px-3 py-1.5 text-xs gap-1.5"> <Plus class="w-3.5 h-3.5" /> Ajouter une question </button> </div> <div v-for="(q, qIdx) in form.questions" :key="qIdx" class="mb-4 rounded-2xl border border-[#01313E]/10 bg-[#01313E]/[.015] overflow-hidden"> <!-- Question header --> <div class="flex items-center gap-3 px-4 py-3 border-b border-[#01313E]/8 bg-white"> <span class="w-6 h-6 rounded-full bg-[#E30046] text-white text-[11px] font-black flex items-center justify-center flex-shrink-0">{{ qIdx + 1 }}</span> <select v-model="q.typeQuestion" class="text-xs font-medium border border-[#01313E]/15 rounded-lg px-2 py-1 text-[#01313E] bg-white focus:outline-none focus:border-[#E30046]"> <option value="CHOIX_UNIQUE">Choix unique</option> <option value="CHOIX_MULTIPLE">Choix multiple</option> </select> <div class="flex items-center gap-1 ml-1"> <input v-model="q.points" type="number" step="0.5" class="w-14 text-xs text-center border border-[#01313E]/15 rounded-lg px-2 py-1 text-[#01313E] bg-white focus:outline-none focus:border-[#E30046]" placeholder="Pts" /> <span class="text-[11px] text-[#01313E]/40">pts</span> </div> <button @click="removeQuestion(qIdx)" class="ml-auto p-1.5 rounded-lg text-[#01313E]/30 hover:bg-[#E30046]/8 hover:text-[#E30046] transition"> <Trash2 class="w-3.5 h-3.5" /> </button> </div> <!-- Question body --> <div class="p-4 space-y-3"> <input v-model="q.intitule" type="text" placeholder="Intitulé de la question…" class="input-field font-semibold" /> <!-- Options --> <div class="pl-1 space-y-2"> <p class="text-[11px] font-bold text-[#01313E]/40 uppercase tracking-wider"> Options — cocher la/les bonne(s) réponse(s) </p> <div v-for="(opt, oIdx) in q.options" :key="oIdx" class="flex items-center gap-2"> <button type="button" @click="selectCorrectOption(qIdx, oIdx)" class="flex-shrink-0 w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all" :class="opt.estCorrecte ? 'bg-[#01313E] border-[#01313E] text-white' : 'border-[#01313E]/20 text-transparent hover:border-[#01313E]/50'"> <Check class="w-3.5 h-3.5" /> </button> <input v-model="opt.texte" type="text" placeholder="Texte de la proposition…" class="flex-1 text-xs border border-[#01313E]/12 rounded-xl px-3 py-2 text-[#01313E] bg-white placeholder:text-[#01313E]/35 focus:outline-none focus:border-[#E30046] transition" :class="opt.estCorrecte ? 'border-[#01313E]/30 bg-[#01313E]/[.02]' : ''" /> <button @click="removeOption(qIdx, oIdx)" class="p-1 rounded-lg text-[#01313E]/25 hover:text-[#E30046] transition"> <X class="w-3.5 h-3.5" /> </button> </div> <button @click="addOption(qIdx)" class="text-[11px] font-bold text-[#01313E]/40 hover:text-[#E30046] flex items-center gap-1 transition mt-1"> <Plus class="w-3 h-3" /> Ajouter une proposition </button> </div> </div> </div> </section> </div> <!-- Modal footer --> <div class="flex items-center justify-end gap-3 px-7 py-5 border-t border-[#01313E]/8 flex-shrink-0"> <button @click="showModalEdit = false" class="btn-secondary px-5 py-2.5 text-sm"> Annuler </button> <button @click="saveTest" class="btn-primary px-5 py-2.5 text-sm"> {{ form.id ? 'Enregistrer les modifications' : 'Créer le QCM' }} </button> </div> </div> </div> </Transition> <!-- ════════════════════════════════════════════════ MODAL — RÉSULTATS CANDIDATS ════════════════════════════════════════════════ --> <Transition enter-active-class="transition duration-200" enter-="opacity-0" enter-="opacity-100" leave-active-class="transition duration-150" leave-="opacity-100" leave-="opacity-0"> <div v-if="showModalPassages" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#01313E]/50 overflow-y-auto" @click.self="showModalPassages = false"> <div class="bg-white rounded-3xl max-w-2xl w-full border border-[#01313E]/10 animate-fade-in max-h-[85vh] flex flex-col"> <!-- Header --> <div class="flex items-center justify-between px-7 py-5 border-b border-[#01313E]/8 flex-shrink-0"> <div> <div class="flex items-center gap-2 mb-0.5"> <BarChart2 class="w-4 h-4 text-[#E30046]" /> <h2 class="text-base font-extrabold text-[#01313E]">Résultats des candidats</h2> </div> <p class="text-xs text-[#01313E]/50">{{ activeTestTitle }}</p> </div> <button @click="showModalPassages = false" class="w-8 h-8 grid place-items-center rounded-lg text-[#01313E]/40 hover:bg-[#01313E]/6 hover:text-[#01313E] transition"> <X class="w-4 h-4" /> </button> </div> <!-- Content --> <div class="flex-1 overflow-y-auto"> <div v-if="selectedPassages.length === 0" class="flex flex-col items-center justify-center py-16 text-center"> <div class="w-12 h-12 rounded-2xl bg-[#01313E]/5 flex items-center justify-center mb-3"> <UserCheck class="w-6 h-6 text-[#01313E]/30" /> </div> <p class="text-sm text-[#01313E]/50">Aucun candidat n'a encore soumis ce test.</p> </div> <div v-else class="divide-y divide-[#01313E]/6"> <div v-for="p in selectedPassages" :key="p.id" class="flex items-center gap-4 px-7 py-4 hover:bg-[#01313E]/[.02] transition"> <!-- Avatar --> <div class="w-9 h-9 rounded-xl bg-[#01313E] text-white text-xs font-black flex items-center justify-center flex-shrink-0"> {{ p.candidatNom?.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase() || '?' }} </div> <div class="flex-1 min-w-0"> <p class="text-sm font-bold text-[#01313E] truncate">{{ p.candidatNom }}</p> <p class="text-xs text-[#01313E]/50 truncate">N° {{ p.candidatureNumero }} · {{ p.candidatEmail }}</p> </div> <div class="text-right flex-shrink-0"> <p class="text-lg font-black text-[#01313E]">{{ p.scoreObtenu }} <span class="text-xs font-medium text-[#01313E]/40">pts</span></p> <span class="badge badge-subtle"> Score enregistré </span> </div> </div> </div> </div> </div> </div> </Transition> </DashboardLayout>
</template>
